import * as assert from 'assert';
import { test } from 'node:test';
import { daemonCommand, parseLaunchFile } from '../daemonLauncher';

/** The daemon is started as java itself, not through bin/'s start scripts (maddi-dist#9). */

const launchText = [
    '# Generated by :maddi-ide-daemon:daemonLaunchFile.',
    'main=io.codelaser.maddi.ide.daemon.DaemonMain',
    'jvm=--add-exports',
    'jvm=jdk.compiler/com.sun.tools.javac.api=ALL-UNNAMED',
    // as many jars as 0.9.7's lib/, with names as long as its longest
    ...Array.from({ length: 60 }, (_, i) => `lib=maddi-modification-analyzer-component-${i}-0.9.7.jar`),
].join('\r\n');

test('the launch description: main class, JVM arguments in order, every jar; CRLF is fine', () => {
    const launch = parseLaunchFile(launchText, 'test');
    assert.strictEqual(launch.mainClass, 'io.codelaser.maddi.ide.daemon.DaemonMain');
    assert.deepStrictEqual(launch.jvmArgs, ['--add-exports', 'jdk.compiler/com.sun.tools.javac.api=ALL-UNNAMED']);
    assert.strictEqual(launch.jars.length, 60);
    assert.throws(() => parseLaunchFile('main=X\n', 'test'), /incomplete/);
    assert.throws(() => parseLaunchFile('main=X\nlib=a.jar\nwhat=y\n', 'test'), /unknown key/);
});

test('on Windows: java.exe, a relative class path that does not grow with the install path', () => {
    const launch = parseLaunchFile(launchText, 'test');
    const jdk = 'C:\\Users\\firstname.lastname\\AppData\\Local\\Programs\\Eclipse Adoptium\\jdk-25.0.1.8-hotspot';
    const { java, args } = daemonCommand(launch, jdk, ['-Xmx8192m', '-XX:+UseG1GC'], true);
    assert.strictEqual(java, jdk + '\\bin\\java.exe');
    assert.ok(!java.endsWith('.bat') && args.every((a) => !a.endsWith('.bat')));
    const classPath = args[args.indexOf('-cp') + 1];
    assert.ok(classPath.startsWith('lib\\maddi-') && classPath.includes(';lib\\'), classPath);
    assert.ok(Math.max(...args.map((a) => a.length)) < 4096);
    assert.ok(java.length + args.reduce((n, a) => n + a.length + 3, 0) < 8191);
    assert.deepStrictEqual(args.slice(-3), ['io.codelaser.maddi.ide.daemon.DaemonMain', '--port', '0']);
    assert.deepStrictEqual(args.slice(0, 4),
        ['--add-exports', 'jdk.compiler/com.sun.tools.javac.api=ALL-UNNAMED', '-Xmx8192m', '-XX:+UseG1GC']);
});

test('on Unix: bin/java and lib/ with colons', () => {
    const { java, args } = daemonCommand(parseLaunchFile(launchText, 'test'), '/opt/jdk', [], false);
    assert.strictEqual(java, '/opt/jdk/bin/java');
    assert.ok(args[args.indexOf('-cp') + 1].startsWith('lib/maddi-'));
    assert.ok(args[args.indexOf('-cp') + 1].includes(':lib/'));
});
